from collections import Counter

def transform(grid):
    # The most common color is the background; connect aligned marker cells.
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        markers = [c for c, value in enumerate(grid[r]) if value != background]
        if len(markers) >= 2:
            for c in range(markers[0] + 1, markers[-1]):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        markers = [r for r in range(h) if grid[r][c] != background]
        if len(markers) >= 2:
            for r in range(markers[0] + 1, markers[-1]):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
